#!/usr/bin/env python3
"""Build the 1,728 editorial draft profiles. No production or sitemap mutation."""
import argparse, html, itertools, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BASE = 'ascendent-soare-luna'
# Each entry: name, slug, element, mode, outward style, identity, emotional need,
# relationship practice, work strength, growth practice.
SIGNS = [
('Berbec','berbec','foc','cardinal','abordezi situațiile direct și preferi să faci primul pas','îți construiești identitatea prin inițiativă, curaj și autonomie','ai nevoie de libertatea de a reacționa sincer și de a relua repede mișcarea după o tensiune','spune ce îți dorești fără a transforma diferențele într-o competiție','a deschide drumuri și a mobiliza o echipă','introdu o pauză între impuls și decizie'),
('Taur','taur','pământ','fix','intri în situații cu prudență, calm și atenție la ceea ce este concret','îți construiești identitatea prin continuitate, valori personale și rezultate durabile','ai nevoie de stabilitate, ritm previzibil și confort senzorial','arată afecțiunea prin consecvență, dar lasă loc schimbării','a administra resurse și a transforma efortul în rezultate stabile','deosebește siguranța reală de simpla obișnuință'),
('Gemeni','gemeni','aer','mutabil','te apropii de oameni prin întrebări, conversație și curiozitate','îți construiești identitatea prin învățare, schimb de idei și explorarea mai multor perspective','ai nevoie să numești ceea ce simți și să poți schimba perspectiva','ascultă răspunsul până la capăt înainte de a deschide un alt subiect','a conecta informații și a explica idei pe înțelesul altora','alege ce merită aprofundat, chiar și după ce dispare noutatea'),
('Rac','rac','apă','cardinal','observi atmosfera emoțională înainte de a te deschide și protejezi ceea ce îți este familiar','îți construiești identitatea prin apartenență, grijă și legături cu semnificație personală','ai nevoie de apropiere, protecție și un spațiu în care vulnerabilitatea este primită','cere sprijin explicit, fără a aștepta ca celălalt să îți ghicească nevoile','a susține oameni și a construi continuitate într-un colectiv','păstrează granițe clare între grijă și asumarea problemelor altora'),
('Leu','leu','foc','fix','te prezinți cu prezență personală, căldură și dorința de a contribui vizibil','îți construiești identitatea prin creativitate, expresie personală și demnitate','ai nevoie de căldură, apreciere sinceră și libertatea de a te exprima','oferă atenție fără a o transforma într-un test de loialitate','a inspira și a da unui proiect o identitate recognoscibilă','separă valoarea ta de reacția imediată a publicului'),
('Fecioară','fecioara','pământ','mutabil','observi detaliile și cauți un mod util și bine pregătit de a participa','îți construiești identitatea prin competență, discernământ și îmbunătățirea lucrurilor','ai nevoie de ordine funcțională, claritate și sentimentul că poți face ceva util','exprimă aprecierea înainte de a propune o corectură','a organiza procese și a identifica ceea ce trebuie ajustat','acceptă un rezultat suficient de bun înainte de perfecționare'),
('Balanță','balanta','aer','cardinal','cauți un ton potrivit, cooperare și echilibru în prima interacțiune','îți construiești identitatea prin relație, alegere conștientă și simțul echității','ai nevoie de reciprocitate, dialog și un climat relațional respectuos','formulează o preferință proprie chiar și atunci când există dezacord','a negocia și a aduce perspective diferite la aceeași masă','nu amâna o decizie doar pentru a evita disconfortul'),
('Scorpion','scorpion','apă','fix','observi cu intensitate și dezvălui treptat ceea ce este personal','îți construiești identitatea prin profunzime, adevăr interior și capacitatea de transformare','ai nevoie de încredere profundă, intimitate și control asupra a ceea ce dezvălui','verifică presupunerile prin întrebări directe, fără teste ascunse','a investiga și a rămâne concentrat în situații complexe','lasă încrederea să se construiască prin fapte, fără a cere certitudine absolută'),
('Săgetător','sagetator','foc','mutabil','te apropii de experiențe cu deschidere, umor și interes pentru posibilități','îți construiești identitatea prin sens, explorare și o viziune personală asupra vieții','ai nevoie de perspectivă, libertate de explorare și speranță','păstrează sinceritatea, dar adaptează momentul și tonul','a vedea direcția de ansamblu și a transmite entuziasm','leagă viziunea de un pas verificabil și de un angajament concret'),
('Capricorn','capricorn','pământ','cardinal','te prezinți rezervat, atent la responsabilități și la credibilitate','îți construiești identitatea prin asumare, structură și realizări cu durată','ai nevoie de fiabilitate, respect și sentimentul că te poți baza pe propriile resurse','arată și nevoia de sprijin, nu doar capacitatea de a rezista','a planifica și a susține un proiect pe termen lung','acordă odihnei un loc real, fără a o condiționa de performanță'),
('Vărsător','varsator','aer','fix','abordezi oamenii cu independență, originalitate și interes pentru idei neobișnuite','îți construiești identitatea prin autonomie intelectuală, inovație și contribuție la un grup','ai nevoie de spațiu personal, libertate de gândire și acceptarea diferențelor','explică nevoia de spațiu fără a dispărea din relație','a regândi sisteme și a conecta oameni în jurul unei idei','rămâi prezent și în conversațiile emoționale care nu au o soluție logică imediată'),
('Pești','pesti','apă','mutabil','percepi subtil atmosfera și te adaptezi intuitiv la oameni și contexte','îți construiești identitatea prin imaginație, empatie și căutarea unei semnificații interioare','ai nevoie de blândețe, retragere periodică și un canal pentru imaginație','numește limitele personale înainte ca adaptarea să devină sacrificiu','a imagina posibilități și a înțelege nuanțele experienței umane','verifică impresia intuitivă prin informații și limite concrete'),
]

def esc(s): return html.escape(s, quote=True)
def slug(a,s,l): return f'ascendent-{a[1]}-soare-{s[1]}-luna-{l[1]}'
def title(a,s,l): return f'Ascendent în {a[0]} · Soare în {s[0]} · Lună în {l[0]}'
def href(a,s,l): return f'/{BASE}/{slug(a,s,l)}/'

def bridge(x,y):
    pair = frozenset((x[2], y[2]))
    if x[1] == y[1]:
        return f'Ambele poziții sunt în {x[0]}. Același limbaj simbolic se repetă și poate face mai ușor de recunoscut această temă. Resursa este coerența; provocarea este să nu folosești aceeași reacție în orice situație.'
    if x[2] == y[2]:
        return f'Cele două semne au în comun elementul {x[2]}. Există o afinitate de ritm și de priorități, deși modul concret de exprimare diferă. Folosește această continuitate pentru a-ți susține intențiile, fără a presupune că nevoile sunt identice.'
    return {
      frozenset(('foc','pământ')):'Entuziasmul întâlnește nevoia de rezultate concrete. O parte vrea să înceapă, iar cealaltă verifică resursele și continuitatea. Un experiment mic, cu termen și buget clare, permite inițiativei să existe fără a sacrifica stabilitatea.',
      frozenset(('foc','aer')):'Impulsul de a acționa întâlnește ideea și dialogul. Conversația poate alimenta inițiativa, iar experiența poate da substanță ideilor. Provocarea este să alegi o direcție și să o duci suficient de departe înainte de următoarea posibilitate.',
      frozenset(('foc','apă')):'Dorința de acțiune se întâlnește cu sensibilitatea față de ceea ce trăiești. Curajul poate proteja ceea ce contează, dar graba poate trece peste un semnal interior. Numește mai întâi emoția, apoi decide ce acțiune îi răspunde cu adevărat.',
      frozenset(('pământ','aer')):'Nevoia de concret se întâlnește cu analiza și schimbul de idei. Gândirea poate îmbunătăți planul, iar practica îi verifică utilitatea. Stabilește un criteriu de decizie pentru a evita atât rigiditatea, cât și analiza fără încheiere.',
      frozenset(('pământ','apă')):'Nevoia de stabilitate întâlnește sensibilitatea și atașamentul. Grija poate primi o formă concretă, prin prezență și continuitate. Ai însă nevoie să deosebești susținerea sănătoasă de păstrarea unei situații doar pentru că este familiară.',
      frozenset(('aer','apă')):'Nevoia de a înțelege întâlnește nevoia de a simți și de a avea încredere. Cuvintele pot clarifica emoția, dar o explicație nu înlocuiește întotdeauna prezența. Alternează întrebarea despre ce s-a întâmplat cu întrebarea despre cum a fost trăită experiența.',
    }[pair]

def synthesis(a,s,l):
    return f'La primul contact, {a[4]}. Dincolo de această impresie, {s[5]}. În plan intim, {l[6]}. Cheia acestei combinații este să verifici dacă felul în care intri într-o situație îți servește direcția personală și îți respectă nevoile emoționale. O aparență sigură nu înseamnă că nu ai nevoie de sprijin, iar o reacție discretă nu spune totul despre ambițiile tale.'

CSS = '''*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:radial-gradient(ellipse at 80% 0,#173d70 0,transparent 48%),#071426;color:#edf4ff;font:17px/1.75 system-ui,sans-serif}a{color:#edd18f;text-underline-offset:4px}a:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #8dd8ff;outline-offset:4px}header,main,footer{max-width:1120px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #c4a46255}header nav{display:flex;gap:18px;flex-wrap:wrap}.brand{font:700 25px Georgia,serif;letter-spacing:3px;text-decoration:none;color:#f3d38f}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#ddc38e}h1,h2,h3{font-family:Georgia,serif;line-height:1.25;overflow-wrap:anywhere}h1{font-size:clamp(30px,5vw,56px);margin:16px 0 24px;max-width:1000px}h2{font-size:29px;color:#f3d592}h3{font-size:22px;color:#f3d592}.lead{font-size:20px;max-width:850px}.hero{width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;border-radius:20px;border:1px solid #d7b87377;background:#132c50}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:28px 0}.card,section{border:1px solid #bba36e55;background:linear-gradient(135deg,#15345988,#0b1c32cc);border-radius:18px;padding:25px;min-width:0}section{margin:20px 0}section p:last-child{margin-bottom:0}.card h2{font-size:22px}.card strong{display:block;color:#e4c384;font-size:13px;letter-spacing:1px}.pill{font-size:13px;border:1px solid #bba36e77;padding:5px 10px;border-radius:30px;display:inline-block;margin:4px 4px 4px 0}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.form label{font-size:15px;color:#e9cf9b}select,button{font:inherit;min-height:48px;width:100%;border:1px solid #c5ab73;border-radius:10px;padding:10px 13px;margin-top:8px}select{background:#112c4c;color:#fff}button,.cta{background:linear-gradient(100deg,#edd299,#ba8b42);color:#08192d;font-weight:700;cursor:pointer}.cta{display:inline-block;padding:12px 24px;border-radius:10px;text-decoration:none}.form button{grid-column:1/-1}.links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.links a{border:1px solid #a88a5355;padding:15px;border-radius:12px;text-decoration:none;background:#102b49}.note,footer{color:#b9c8dd;font-size:14px}.note{max-width:850px}.crumb{font-size:14px;margin-bottom:30px}article{max-width:900px}footer{border-top:1px solid #c4a46255;margin-top:35px}.draft{font-size:13px;color:#e6d0a6}.inline{display:inline}.selector-title{margin-top:0}@media(max-width:680px){header,main,footer{padding:18px}.triptych,.form,.links{grid-template-columns:1fr}.card,section{padding:20px}.lead{font-size:18px}header{align-items:flex-start;flex-direction:column;gap:8px}h1{font-size:32px}.triptych{gap:12px}.card h2{margin:8px 0}.card p{margin:10px 0}section h2{font-size:25px}}'''

def form(a=0,s=0,l=0):
    fields=[]
    for label,idx,k in [('Ascendent',a,'asc'),('Soare',s,'sun'),('Lună',l,'moon')]:
        options=''.join(f'<option value="{x[1]}"'+(' selected' if i==idx else '')+f'>{x[0]}</option>' for i,x in enumerate(SIGNS))
        fields.append(f'<label for="{k}">{label}<select id="{k}" name="{k}">{options}</select></label>')
    return '<section><h2 class="selector-title">Alege combinația ta</h2><form class="form" id="profile-form">'+''.join(fields)+'<button type="submit">Descoperă interpretarea</button></form><noscript><p>Alege Ascendentul din lista de mai jos și navighează către combinația dorită.</p></noscript></section>'

def document(t,desc,path,body,depth=0):
    # Relative links make the package browsable offline, while canonical URLs stay absolute.
    prefix='../'*(depth+1)
    asset=prefix+'assets/triplu-profil/'
    site='https://astrovip.ro'
    schema={'@context':'https://schema.org','@type':'WebPage','name':t,'description':desc,'url':site+path,'inLanguage':'ro-RO','isPartOf':{'@type':'WebSite','@id':site+'/#website','name':'AstroVip','url':site+'/'}}
    return f'''<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(t)} | AstroVip</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="{site}{path}"><meta property="og:title" content="{esc(t)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{site}{path}"><meta property="og:image" content="{site}/assets/triplu-profil/hero.webp"><link rel="stylesheet" href="{asset}style.css"><script src="{asset}select.js" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><header><a class="brand" href="{site}/">ASTROVIP</a><nav aria-label="Navigare principală"><a href="{site}/harta-natala/">Harta natală</a><a href="{site}/despre-astrovip/">Despre AstroVip</a></nav></header><main><p class="draft">PREVIEW EDITORIAL · Colecție în pregătire</p>{body}</main><footer><p>AstroVip · Astrologie premium</p><p>Lectură simbolică generală a celor trei poziții. Interpretarea individuală se nuanțează prin grade, case, aspecte și stăpânii semnelor. Pozițiile pe semne nu confirmă singure aspecte exacte și nu descriu un destin obligatoriu.</p><a href="{site}/harta-natala/">Descoperă harta natală completă</a></footer></body></html>'''

def page(a,s,l):
    t=title(a,s,l)
    cards=''
    for label,x,body in [('ASCENDENT',a,a[4]),('SOARE',s,s[5]),('LUNĂ',l,l[6])]:
        cards+=f'<div class="card"><strong>{label}</strong><h2>{x[0]}</h2><span class="pill">{x[2].capitalize()}</span><span class="pill">{x[3].capitalize()}</span><p>{esc(body[0].upper()+body[1:])}.</p></div>'
    blocks=[('Portretul combinației',synthesis(a,s,l)),('Ascendent și Soare: prezență și direcție',f'Ascendentul în {a[0]} descrie stilul de intrare în experiență; Soarele în {s[0]} arată tema identității și a voinței. '+bridge(a,s)),('Soare și Lună: voință și nevoi emoționale',f'Soarele în {s[0]} poate orienta alegerile conștiente, în timp ce Luna în {l[0]} descrie un limbaj al confortului și al reacțiilor familiare. '+bridge(s,l)),('Ascendent și Lună: ce se vede și ce simți',f'Felul în care pari, cu Ascendentul în {a[0]}, nu epuizează ceea ce trăiești cu Luna în {l[0]}. '+bridge(a,l)),('Relații și apropiere',f'În relații, prima impresie vine adesea din felul în care {a[4]}. Pe măsură ce apropierea crește, devine relevant faptul că {l[6]}. O practică utilă pentru această nevoie: {l[7]}. În același timp, direcția Soarelui în {s[0]} cere să îți păstrezi valorile personale. Nu deduce compatibilitatea cu o persoană doar din aceste trei semne; dialogul concret și întreaga hartă aduc informația care lipsește.'),('Muncă, resurse și dezvoltare',f'Ca temă simbolică de dezvoltare, Soarele în {s[0]} poate pune în valoare capacitatea de {s[8]}. Ascendentul în {a[0]} influențează modul de a începe un proiect, iar Luna în {l[0]} poate arăta ce atmosferă îți susține continuitatea. Pentru echilibru, {s[9]}. Aceste repere nu stabilesc o profesie și nu înlocuiesc analiza MC-ului, a caselor relevante, a aptitudinilor și a experienței tale.'),('Un exercițiu pentru integrare',f'Alege o situație recentă și notează trei răspunsuri: cum ai intrat în ea, ce voiai să construiești și de ce aveai nevoie pentru a te simți în siguranță. Compară răspunsurile cu Ascendentul în {a[0]}, Soarele în {s[0]} și Luna în {l[0]}. Dacă observi o tensiune, încearcă această ajustare: {a[9]}. Pentru reglarea emoțională, {l[9]}. Păstrează ceea ce se verifică în experiența ta, fără a forța descrierea.')]
    sections=''.join(f'<section><h2>{h}</h2><p>{esc(p)}</p></section>' for h,p in blocks)
    peers=[]
    # Discoverable, bounded navigation in each dimension.
    for label,idx in [('Schimbă Ascendentul',0),('Schimbă Soarele',1),('Schimbă Luna',2)]:
        links=[]
        for x in SIGNS:
            combo=[a,s,l]; combo[idx]=x
            links.append(f'<a href="../{slug(*combo)}/index.html">{x[0]}</a>')
        peers.append(f'<section><h2>{label}</h2><div class="links">'+''.join(links)+'</div></section>')
    body=f'<nav class="crumb" aria-label="Fir de navigare"><a href="../index.html">Ascendent · Soare · Lună</a></nav><p class="eyebrow">Trei repere · un portret interior</p><h1>{t}</h1><p class="lead">Cum se întâlnesc stilul tău de exprimare, identitatea și nevoile emoționale.</p><img class="hero" src="../../assets/triplu-profil/hero.webp" width="1536" height="864" alt="Ilustrație AstroVip: orizont auriu, Soare și Lună pe fundal albastru cosmic" fetchpriority="high"><div class="triptych">{cards}</div><article>{sections}<section><h2>De la trei semne la harta ta completă</h2><p>Această pagină oferă repere generale. Pentru o analiză individuală sunt necesare data, ora corectă și locul nașterii, apoi examinarea întregii hărți.</p><a class="cta" href="https://astrovip.ro/harta-natala/">Explorează harta natală</a></section></article>'+form(SIGNS.index(a),SIGNS.index(s),SIGNS.index(l))+''.join(peers)
    return document(t,f'Interpretare astrologică pentru Ascendent în {a[0]}, Soare în {s[0]} și Lună în {l[0]}: identitate, emoții, relații și dezvoltare.',href(a,s,l),body,1)

def build(out):
    target=out/BASE; target.mkdir(parents=True,exist_ok=True)
    assets=out/'assets/triplu-profil'; assets.mkdir(parents=True,exist_ok=True)
    (assets/'style.css').write_text(CSS)
    (assets/'select.js').write_text('''const form=document.getElementById('profile-form');if(form)form.addEventListener('submit',event=>{event.preventDefault();const a=form.elements.asc.value,s=form.elements.sun.value,l=form.elements.moon.value;const parts=location.pathname.split('/');const i=parts.indexOf('ascendent-soare-luna');const base=parts.slice(0,i+1).join('/');location.href=base+'/ascendent-'+a+'-soare-'+s+'-luna-'+l+'/index.html';});''')
    for a,s,l in itertools.product(SIGNS, repeat=3):
        dest=target/slug(a,s,l); dest.mkdir(exist_ok=True)
        (dest/'index.html').write_text(page(a,s,l),encoding='utf-8')
    links=''.join(f'<a href="ascendent-{a[1]}/index.html">Ascendent în {a[0]}<br><span class="note">144 combinații Soare–Lună</span></a>' for a in SIGNS)
    body='<p class="eyebrow">Colecția AstroVip</p><h1>Ascendent · Soare · Lună</h1><p class="lead">1.728 de combinații pentru a explora relația dintre felul în care te exprimi, ceea ce vrei să devii și ceea ce ai nevoie să simți.</p><img class="hero" src="../assets/triplu-profil/hero.webp" width="1536" height="864" alt="Cele trei repere astrologice: Ascendent, Soare și Lună">'+form()+'<section><h2>Explorează după Ascendent</h2><div class="links">'+links+'</div></section><section><h2>Trei poziții, roluri diferite</h2><p>Ascendentul descrie modul de abordare a experienței. Soarele vorbește despre identitate și direcție. Luna este asociată cu nevoile emoționale și reacțiile familiare. Interpretările combină aceste roluri, afinitățile elementelor și practicile de integrare.</p><p>Ora nașterii este esențială pentru Ascendent. În apropierea unei schimbări de semn, verifică pozițiile prin calcul înainte de a alege profilul.</p></section>'
    (target/'index.html').write_text(document('Ascendent, Soare și Lună: cele 1.728 de combinații','Explorează combinațiile Ascendent–Soare–Lună și relația dintre identitate, prezență și nevoile emoționale.',f'/{BASE}/',body))
    for a in SIGNS:
        groups=[]
        for s in SIGNS:
            links=''.join(f'<a href="../{slug(a,s,l)}/index.html">Lună în {l[0]}</a>' for l in SIGNS)
            groups.append(f'<section><h2>Soare în {s[0]}</h2><div class="links">{links}</div></section>')
        dest=target/f'ascendent-{a[1]}';dest.mkdir(exist_ok=True)
        (dest/'index.html').write_text(document(f'Ascendent în {a[0]}: toate combinațiile Soare–Lună',f'Cele 144 de combinații cu Ascendent în {a[0]}.',f'/{BASE}/ascendent-{a[1]}/',f'<a href="../index.html">Toată colecția</a><h1>Ascendent în {a[0]}</h1><p class="lead">Alege semnul Soarelui, apoi semnul Lunii.</p>'+''.join(groups),1))
    (out/'README.txt').write_text('ASTROVIP — PREVIEW EDITORIAL\n1.728 profiluri + 12 pagini Ascendent + 1 index.\nToate paginile sunt noindex,follow. Nu s-a modificat site-ul live sau sitemapul.\nDeschide ascendent-soare-luna/index.html.\nIlustrația este comună colecției; nu sunt 1.728 de imagini individuale.\nTextele sunt drafturi compuse modular din poziții și perechi de elemente, fără aspecte deduse din semne. Nu sunt semnate ca texte revizuite de Cătălin Smaranda.\nRevizuire editorială și verificare vizuală înainte de publicare.\nPentru regenerare: python3 build.py --output DIRECTOR\n')
    print(json.dumps({'profiles':1728,'hubs':13,'output':str(out),'robots':'noindex,follow'},ensure_ascii=False))

